#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    scripts/types
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Moves each folder's exported types into that folder's `types.ts` (organization contract, Rule 8a).
 *
 * A type declared beside the one function that returns it is invisible to the module next door, so
 * that module declares its own, and one idea ends up with three names. Rule 8a puts them in one
 * place per folder. There were 237 files in breach, which is a codemod's job, not a week of hand
 * edits — but only if the codemod refuses whatever it cannot move safely, and says why.
 *
 * For each folder: every exported `type`, `interface` and `enum` moves to `<folder>/types.ts`, with
 * its own doc comment and the imports it needs. A private type that only moving types use moves
 * with them. Every relative importer of a moved name — in src, tests, tooling, mcp and scripts —
 * is repointed at `types.ts`, and a barrel that stars the old module also stars `./types`.
 *
 * It REFUSES, per type, and reports:
 *   - a type that reads a value in its own file (`typeof CATALOG`): it belongs beside that value,
 *     and a types module importing its sibling's values is a cycle waiting to happen;
 *   - a type that leans on a private type something else in the file still uses;
 *   - a name declared twice in one file (a type merged with a value);
 *   - a name two files in one folder both export — which of them is meant is a judgement.
 *
 *   node scripts/move-types-to-types-module.mjs            # dry run: what would move, what cannot
 *   node scripts/move-types-to-types-module.mjs --write
 *   node scripts/move-types-to-types-module.mjs --only mechanics/bots [--write]
 */
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import ts from 'typescript'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const MONOREPO_ROOT = path.resolve(PACKAGE_ROOT, '..', '..')
const SRC = path.join(PACKAGE_ROOT, 'src')
const WRITE = process.argv.includes('--write')
const onlyAt = process.argv.indexOf('--only')
const ONLY = onlyAt >= 0 ? process.argv[onlyAt + 1] : null

const posix = value => value.split(path.sep).join('/')
const rel = file => posix(path.relative(SRC, file))
const isGenerated = r => /(^|\/)generated\//.test(r) || /\.generated\.ts$/.test(r)

const SKIP_DIRS = new Set(['node_modules', 'dist', '.git', 'build', 'coverage', 'dumps', '.svelte-kit', 'site'])
function walk(dir, pattern, out = []) {
  if (!existsSync(dir)) return out
  for (const entry of readdirSync(dir)) {
    if (SKIP_DIRS.has(entry)) continue
    const full = path.join(dir, entry)
    if (statSync(full).isDirectory()) walk(full, pattern, out)
    else if (pattern.test(entry) && !entry.endsWith('.d.ts')) out.push(full)
  }
  return out
}

function resolveSpecifier(fromFile, specifier) {
  const base = path.resolve(path.dirname(fromFile), specifier)
  return [`${base}.ts`, path.join(base, 'index.ts'), base]
    .find(candidate => existsSync(candidate) && statSync(candidate).isFile()) ?? null
}

function toSpecifier(fromDir, target) {
  let out = posix(path.relative(fromDir, target)).replace(/\.ts$/, '')
  if (!out.startsWith('.')) out = `./${out}`
  return out
}

/* ── reading one module ───────────────────────────────────────────────────── */

function bindingNames(name) {
  if (ts.isIdentifier(name)) return [name.text]
  return name.elements.flatMap(element => (ts.isOmittedExpression(element) ? [] : bindingNames(element.name)))
}

function declaredNames(statement) {
  if (ts.isFunctionDeclaration(statement) || ts.isClassDeclaration(statement)
    || ts.isInterfaceDeclaration(statement) || ts.isTypeAliasDeclaration(statement)
    || ts.isEnumDeclaration(statement) || ts.isModuleDeclaration(statement)) {
    return statement.name && ts.isIdentifier(statement.name) ? [statement.name.text] : []
  }
  if (ts.isVariableStatement(statement)) {
    return statement.declarationList.declarations.flatMap(declaration => bindingNames(declaration.name))
  }
  return []
}

const modifiersOf = statement => (ts.canHaveModifiers(statement) ? ts.getModifiers(statement) ?? [] : [])
const hasModifier = (statement, kind) => modifiersOf(statement).some(modifier => modifier.kind === kind)

/** Identifiers a statement mentions, minus the ones that only name a property or a parameter. */
function referencedNames(node) {
  const out = new Set()
  const visit = current => {
    if (ts.isIdentifier(current)) {
      const parent = current.parent
      const namesSomethingElse = parent && (
        ((ts.isPropertyAccessExpression(parent) || ts.isPropertyAssignment(parent) || ts.isPropertySignature(parent)
          || ts.isPropertyDeclaration(parent) || ts.isMethodSignature(parent) || ts.isMethodDeclaration(parent)
          || ts.isEnumMember(parent) || ts.isGetAccessor(parent) || ts.isSetAccessor(parent)
          || ts.isParameter(parent) || ts.isTypeParameterDeclaration(parent)) && parent.name === current)
        || (ts.isQualifiedName(parent) && parent.right === current)
        || (ts.isBindingElement(parent) && parent.propertyName === current)
      )
      if (!namesSomethingElse) out.add(current.text)
    }
    ts.forEachChild(current, visit)
  }
  visit(node)
  return out
}

function analyze(file) {
  const text = readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const infos = sf.statements.map((statement, index) => {
    const names = declaredNames(statement)
    const refs = referencedNames(statement)
    for (const name of names) refs.delete(name)
    const isType = ts.isInterfaceDeclaration(statement) || ts.isTypeAliasDeclaration(statement)
    const isEnum = ts.isEnumDeclaration(statement)
    return {
      statement,
      index,
      names,
      refs,
      exported: hasModifier(statement, ts.SyntaxKind.ExportKeyword),
      isDefault: hasModifier(statement, ts.SyntaxKind.DefaultKeyword),
      kind: ts.isImportDeclaration(statement) ? 'import'
        : ts.isExportDeclaration(statement) || ts.isExportAssignment(statement) ? 'reexport'
          : isType ? 'type' : isEnum ? 'enum' : names.length ? 'value' : 'other',
    }
  })

  /** local name → where it was imported from */
  const imports = new Map()
  for (const info of infos.filter(candidate => candidate.kind === 'import')) {
    const clause = info.statement.importClause
    if (!clause || !ts.isStringLiteral(info.statement.moduleSpecifier)) continue
    const specifier = info.statement.moduleSpecifier.text
    if (clause.name) imports.set(clause.name.text, { specifier, kind: 'default', clauseTypeOnly: clause.isTypeOnly })
    const bindings = clause.namedBindings
    if (bindings && ts.isNamespaceImport(bindings)) {
      imports.set(bindings.name.text, { specifier, kind: 'namespace', clauseTypeOnly: clause.isTypeOnly })
    }
    if (bindings && ts.isNamedImports(bindings)) {
      for (const element of bindings.elements) {
        imports.set(element.name.text, {
          specifier,
          kind: 'named',
          imported: (element.propertyName ?? element.name).text,
          clauseTypeOnly: clause.isTypeOnly || element.isTypeOnly,
        })
      }
    }
  }
  return { file, text, sf, infos, imports }
}

/** Decide which exported types in one module can move, and why the rest cannot. */
function plan(module) {
  const { infos } = module
  const byName = new Map()
  const doubled = new Set()
  for (const info of infos) {
    for (const name of info.names) {
      if (byName.has(name)) doubled.add(name)
      byName.set(name, info)
    }
  }

  const rejected = []
  const moving = new Set()
  for (const info of infos) {
    if (!info.exported || info.isDefault || (info.kind !== 'type' && info.kind !== 'enum')) continue
    if (info.names.some(name => doubled.has(name))) {
      rejected.push({ name: info.names.join(', '), why: 'declared twice here (a type merged with a value)' })
      continue
    }
    moving.add(info)
  }

  const usedOutside = candidate => infos.some(other =>
    other !== candidate && !moving.has(other) && other.kind !== 'import'
    && candidate.names.some(name => other.refs.has(name)))

  for (let changed = true; changed;) {
    changed = false
    for (const info of [...moving]) {
      for (const ref of info.refs) {
        const local = byName.get(ref)
        if (!local || local === info || moving.has(local)) continue
        if (local.kind === 'type' && !local.exported && !usedOutside(local)) {
          moving.add(local)
          changed = true
          continue
        }
        moving.delete(info)
        if (info.exported) {
          rejected.push({
            name: info.names.join(', '),
            why: local.kind === 'value' || local.kind === 'enum'
              ? `reads the value '${ref}' declared beside it`
              : `leans on the private type '${ref}', which other code here still uses`,
          })
        }
        changed = true
        break
      }
    }
  }

  // A private type pulled in earlier may have lost the exported type that needed it.
  for (const info of [...moving]) {
    if (info.exported) continue
    const stillNeeded = [...moving].some(other => other !== info && info.names.some(name => other.refs.has(name)))
    if (!stillNeeded) moving.delete(info)
  }

  // A local `export { … }` list naming a leaving type would dangle.
  const exportLists = infos.filter(info => info.kind === 'reexport' && ts.isExportDeclaration(info.statement)
    && !info.statement.moduleSpecifier)
  for (const info of [...moving]) {
    if (exportLists.some(list => info.names.some(name => list.refs.has(name)))) {
      moving.delete(info)
      rejected.push({ name: info.names.join(', '), why: 'named in a local export list' })
    }
  }

  return { moving, rejected }
}

/** The text of a statement with its own doc comment, never the file's header. */
function spanOf(module, info) {
  const { text, sf } = module
  const statement = info.statement
  let start = statement.getStart(sf)
  const ranges = ts.getLeadingCommentRanges(text, statement.getFullStart()) ?? []
  const isFirst = info.index === 0
  for (let i = ranges.length - 1; i >= 0; i--) {
    const range = ranges[i]
    const gapEnd = i === ranges.length - 1 ? statement.getStart(sf) : ranges[i + 1].pos
    if (/\n[ \t]*\r?\n/.test(text.slice(range.end, gapEnd))) break
    const body = text.slice(range.pos, range.end)
    if (body.includes('── file map') || !body.startsWith('/**')) break
    // The first statement's doc comment may be the file's own docblock; leave that one.
    if (isFirst && !ranges.slice(0, i).some(r => /^\/\*\*[\s\S]{60,}\*\/$/.test(text.slice(r.pos, r.end))
      && !text.slice(r.pos, r.end).includes('── file map'))) break
    start = range.pos
  }
  let end = statement.getEnd()
  if (text.slice(end, end + 2) === '\r\n') end += 2
  else if (text[end] === '\n') end += 1
  return { start, end, body: text.slice(start, statement.getEnd()) }
}

/* ── the folder pass ──────────────────────────────────────────────────────── */

function main() {
  const sources = walk(SRC, /\.ts$/).filter(file => {
    const r = rel(file)
    const base = path.basename(file)
    if (isGenerated(r) || base === 'index.ts' || base === 'types.ts') return false
    return !ONLY || r.startsWith(`${ONLY}/`) || path.dirname(r) === ONLY
  })

  const byFolder = new Map()
  for (const file of sources) {
    const dir = path.dirname(file)
    if (!byFolder.has(dir)) byFolder.set(dir, [])
    byFolder.get(dir).push(file)
  }

  /** absolute source file → Set of names leaving it */
  const leaving = new Map()
  const report = []
  const writes = new Map()

  for (const [dir, files] of byFolder) {
    const typesFile = path.join(dir, 'types.ts')
    const existingTypes = existsSync(typesFile) ? analyze(typesFile) : null
    const taken = new Set(existingTypes ? existingTypes.infos.flatMap(info => info.names) : [])

    const perFile = []
    for (const file of files) {
      const module = analyze(file)
      const { moving, rejected } = plan(module)
      if (moving.size === 0 && rejected.length === 0) continue
      perFile.push({ module, moving, rejected })
    }
    if (perFile.length === 0) continue

    // A name two files here both export cannot go to one module without choosing between them.
    const owners = new Map()
    for (const entry of perFile) {
      for (const info of entry.moving) for (const name of info.names) {
        owners.set(name, [...(owners.get(name) ?? []), entry])
      }
    }
    for (const entry of perFile) {
      for (const info of [...entry.moving]) {
        const clash = info.names.find(name => (owners.get(name)?.length ?? 0) > 1 || taken.has(name))
        if (clash) {
          entry.moving.delete(info)
          if (info.exported) entry.rejected.push({ name: clash, why: 'another module in this folder exports the same name' })
        }
      }
    }

    const folderMoved = new Set(perFile.flatMap(entry => [...entry.moving].flatMap(info => info.names)))
    const blocks = []
    /** resolved target (or bare specifier) → { specifier, typeOnly: Set, value: Set, extra: Set } */
    const needs = new Map()
    const need = (key, specifier) => {
      if (!needs.has(key)) needs.set(key, { specifier, typeNames: new Set(), valueNames: new Set(), lines: new Set() })
      return needs.get(key)
    }

    for (const entry of perFile) {
      const { module, moving, rejected } = entry
      for (const item of rejected) report.push(`  refused  ${rel(module.file)}: ${item.name} — ${item.why}`)
      if (moving.size === 0) continue

      const ordered = [...moving].sort((a, b) => a.index - b.index)
      const spans = ordered.map(info => ({ info, ...spanOf(module, info) }))
      blocks.push(`// from ${path.basename(module.file)}`)
      for (const span of spans) blocks.push(span.body)

      // Imports the moved declarations need, re-expressed from types.ts (same folder: same specifiers).
      for (const info of ordered) {
        for (const ref of info.refs) {
          const from = module.imports.get(ref)
          if (!from) continue
          const target = from.specifier.startsWith('.') ? resolveSpecifier(module.file, from.specifier) : null
          if (target && path.dirname(target) === dir && folderMoved.has(from.imported ?? ref)) continue
          const key = target ?? from.specifier
          const slot = need(key, from.specifier)
          if (from.kind === 'default') slot.lines.add(`import ${ref} from '${from.specifier}'`)
          else if (from.kind === 'namespace') slot.lines.add(`import ${info.kind === 'enum' ? '' : 'type '}* as ${ref} from '${from.specifier}'`)
          else {
            const element = from.imported !== ref ? `${from.imported} as ${ref}` : ref
            if (info.kind === 'enum' && !from.clauseTypeOnly) slot.valueNames.add(element)
            else slot.typeNames.add(element)
          }
        }
      }

      // The source loses the declarations and imports back what it still uses.
      const movedHere = new Set(ordered.flatMap(info => info.names))
      leaving.set(module.file, new Set(ordered.filter(info => info.exported).flatMap(info => info.names)))
      let text = module.text
      for (const span of [...spans].sort((a, b) => b.start - a.start)) {
        text = text.slice(0, span.start) + text.slice(span.end)
      }
      const remaining = module.infos.filter(info => !moving.has(info) && info.kind !== 'import')
      const stillUsed = [...movedHere].filter(name => remaining.some(info => info.refs.has(name)))
      if (stillUsed.length > 0) {
        const enumNames = new Set(ordered.filter(info => info.kind === 'enum').flatMap(info => info.names))
        const allTypes = stillUsed.every(name => !enumNames.has(name))
        const elements = stillUsed.sort().map(name => (!allTypes || enumNames.has(name) ? (enumNames.has(name) ? name : `type ${name}`) : name))
        // The file's own line ending: an LF line inside a CRLF file glues onto the next line for
        // any tool that splits on CRLF, which is how four files defeated the first repair.
        const eol = text.includes('\r\n') ? '\r\n' : '\n'
        const line = `${allTypes ? 'import type' : 'import'} { ${elements.join(', ')} } from './types'${eol}`
        const lastImport = module.infos.filter(info => info.kind === 'import').at(-1)
        const at = lastImport ? afterStatement(text, lastImport.statement.getText(module.sf))
          : insertionPointAfterHeader(text)
        text = text.slice(0, at) + line + text.slice(at)
      }
      writes.set(module.file, collapseBlankRuns(text))
      report.push(`  move     ${rel(module.file)}: ${ordered.map(info => (info.exported ? '' : '(private) ') + info.names.join(', ')).join('; ')}`)
    }

    if (blocks.length === 0) continue
    const importLines = []
    for (const slot of [...needs.values()].sort((a, b) => a.specifier.localeCompare(b.specifier))) {
      for (const line of slot.lines) importLines.push(line)
      const typeOnly = [...slot.typeNames].filter(name => !slot.valueNames.has(name))
      if (slot.valueNames.size > 0) {
        importLines.push(`import { ${[...[...slot.valueNames].sort(), ...typeOnly.sort().map(name => `type ${name}`)].join(', ')} } from '${slot.specifier}'`)
      }
      else if (typeOnly.length > 0) importLines.push(`import type { ${typeOnly.sort().join(', ')} } from '${slot.specifier}'`)
    }

    const folder = rel(dir)
    let out
    if (existingTypes) {
      out = `${existingTypes.text.trimEnd()}\n\n${blocks.join('\n\n')}\n`
      if (importLines.length > 0) {
        const lastImport = existingTypes.infos.filter(info => info.kind === 'import').at(-1)
        const at = lastImport ? afterStatement(out, lastImport.statement.getText(existingTypes.sf))
          : insertionPointAfterHeader(out)
        out = out.slice(0, at) + importLines.join('\n') + '\n' + out.slice(at)
      }
    }
    else {
      out = [
        '/**',
        ` * The types \`${folder}/\` exports, in one place — so a neighbouring module finds the shape it`,
        ' * needs here instead of declaring its own under a second name.',
        ' */',
        ...importLines,
        '',
        blocks.join('\n\n'),
        '',
      ].join('\n')
    }
    writes.set(typesFile, collapseBlankRuns(out))
  }

  const importers = rewriteImporters(leaving, writes)

  console.log(report.join('\n'))
  const moved = [...leaving.values()].reduce((sum, names) => sum + names.size, 0)
  const refused = report.filter(line => line.startsWith('  refused')).length
  console.log(`\n${moved} exported types leave ${leaving.size} modules; ${refused} refused; ${importers} importers repointed.`)
  if (!WRITE) {
    console.log('dry run — nothing written. Re-run with --write.')
    return
  }
  for (const [file, text] of writes) writeFileSync(file, text)
  console.log(`wrote ${writes.size} files.`)
}

/**
 * The offset just past the line that ENDS a statement.
 *
 * The first version searched for the first newline after the statement's start, which for a
 * multi-line import is inside its braces — 36 files came out unparseable. The end of the text is
 * the end of the statement, however many lines it spans.
 */
function afterStatement(text, statementText) {
  const end = text.indexOf(statementText) + statementText.length
  const newline = text.indexOf('\n', end)
  return newline < 0 ? text.length : newline + 1
}

/** Squeeze runs of blank lines to one, in whichever line ending the file uses. */
function collapseBlankRuns(text) {
  const eol = text.includes('\r\n') ? '\r\n' : '\n'
  return text.replace(/(?:[ \t]*\r?\n){3,}/g, eol + eol)
}

function insertionPointAfterHeader(text) {
  let at = 0
  const re = /^\s*\/\*[\s\S]*?\*\/[ \t]*\r?\n/y
  for (let match = re.exec(text); match; match = re.exec(text)) at = re.lastIndex
  return at
}

/**
 * Point every relative importer of a leaving name at its new module.
 *
 * Named imports and named re-exports are split; `export * from` a module that lost types gains a
 * sibling `export * from '<dir>/types'`, once. A namespace import of a leaving module is reported,
 * because `ns.Type` cannot be repointed by moving a specifier.
 */
function rewriteImporters(leaving, writes) {
  const scope = [
    ...walk(SRC, /\.ts$/),
    ...walk(path.join(PACKAGE_ROOT, 'tests'), /\.(ts|mts)$/),
    ...walk(path.join(PACKAGE_ROOT, 'tooling'), /\.(ts|mts)$/),
    ...walk(path.join(PACKAGE_ROOT, 'mcp'), /\.(ts|mts)$/),
    ...walk(path.join(PACKAGE_ROOT, 'scripts'), /\.(ts|mts)$/),
    ...walk(path.join(MONOREPO_ROOT, 'scripts'), /\.(ts|mts)$/),
  ]
  let count = 0
  for (const file of scope) {
    const text = writes.get(file) ?? readFileSync(file, 'utf8')
    if (!text.includes('from')) continue
    const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
    const edits = []
    const starred = new Set(
      sf.statements.filter(s => ts.isExportDeclaration(s) && !s.exportClause && s.moduleSpecifier
        && ts.isStringLiteral(s.moduleSpecifier))
        .map(s => resolveSpecifier(file, s.moduleSpecifier.text)),
    )
    for (const statement of sf.statements) {
      const isImport = ts.isImportDeclaration(statement)
      const isExport = ts.isExportDeclaration(statement)
      if (!(isImport || isExport) || !statement.moduleSpecifier || !ts.isStringLiteral(statement.moduleSpecifier)) continue
      const specifier = statement.moduleSpecifier.text
      if (!specifier.startsWith('.')) continue
      const target = resolveSpecifier(file, specifier)
      const names = target && leaving.get(target)
      if (!names || names.size === 0) continue
      const typesSpecifier = toSpecifier(path.dirname(file), path.join(path.dirname(target), 'types.ts'))

      if (isExport && !statement.exportClause) {
        const typesTarget = path.join(path.dirname(target), 'types.ts')
        if (!starred.has(typesTarget) && typesTarget !== file) {
          starred.add(typesTarget)
          edits.push({ start: statement.getEnd(), end: statement.getEnd(), text: `\nexport * from '${typesSpecifier}'` })
          count++
        }
        continue
      }
      const bindings = isImport ? statement.importClause?.namedBindings : statement.exportClause
      if (!bindings) continue
      if (ts.isNamespaceImport(bindings)) {
        console.log(`  note     ${posix(path.relative(PACKAGE_ROOT, file))}: namespace import of ${specifier} — check any .Type use by hand`)
        continue
      }
      if (!('elements' in bindings)) continue
      const clauseTypeOnly = isImport ? statement.importClause.isTypeOnly : statement.isTypeOnly
      const stay = []
      const go = []
      for (const element of bindings.elements) {
        const name = (element.propertyName ?? element.name).text
        ;(names.has(name) ? go : stay).push(element.getText(sf))
      }
      if (go.length === 0) continue
      const keyword = isImport ? 'import' : 'export'
      const head = `${keyword}${clauseTypeOnly ? ' type' : ''}`
      const lines = []
      if (stay.length > 0) lines.push(`${head} { ${stay.join(', ')} } from '${specifier}'`)
      lines.push(`${head} { ${go.join(', ')} } from '${typesSpecifier}'`)
      edits.push({ start: statement.getStart(sf), end: statement.getEnd(), text: lines.join('\n') })
      count++
    }
    if (edits.length === 0) continue
    let out = text
    for (const edit of edits.sort((a, b) => b.start - a.start)) out = out.slice(0, edit.start) + edit.text + out.slice(edit.end)
    writes.set(file, out)
  }
  return count
}

/* ── the repoint pass ─────────────────────────────────────────────────────── */

const exportCache = new Map()

/** Every name a module exports: declarations, local export lists, named and star re-exports. */
function exportedNames(file, seen = new Set()) {
  if (exportCache.has(file)) return exportCache.get(file)
  if (seen.has(file) || !existsSync(file)) return new Set()
  seen.add(file)
  const text = readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
  const out = new Set()
  for (const statement of sf.statements) {
    if (hasModifier(statement, ts.SyntaxKind.ExportKeyword)) for (const name of declaredNames(statement)) out.add(name)
    if (!ts.isExportDeclaration(statement)) continue
    if (statement.exportClause && ts.isNamedExports(statement.exportClause)) {
      for (const element of statement.exportClause.elements) out.add(element.name.text)
    }
    else if (!statement.exportClause && statement.moduleSpecifier && ts.isStringLiteral(statement.moduleSpecifier)) {
      const target = statement.moduleSpecifier.text.startsWith('.') ? resolveSpecifier(file, statement.moduleSpecifier.text) : null
      if (target) for (const name of exportedNames(target, seen)) out.add(name)
    }
  }
  exportCache.set(file, out)
  return out
}

/**
 * Repoint every relative import of a name its module no longer exports, where that module's
 * folder `types.ts` now does.
 *
 * The first pass chose its importers from the files that existed BEFORE the run, so the new
 * `types.ts` files — which import from other folders whose types were leaving in the same run —
 * never had their own imports repointed; and files the run left unparseable were skipped. This
 * reads the finished tree instead, so it has nothing to be early for. A name imported twice once
 * both point at the same module is dropped, and `import('./x').Name` type queries are rewritten.
 */
function repointDangling() {
  const scope = [
    ...walk(SRC, /\.ts$/),
    ...walk(path.join(PACKAGE_ROOT, 'tests'), /\.(ts|mts)$/),
    ...walk(path.join(PACKAGE_ROOT, 'tooling'), /\.(ts|mts)$/),
    ...walk(path.join(PACKAGE_ROOT, 'mcp'), /\.(ts|mts)$/),
  ]
  let files = 0
  let moved = 0
  for (const file of scope) {
    const text = readFileSync(file, 'utf8')
    const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS)
    const edits = []
    /** local names already bound by an import, so a second binding is a duplicate */
    const bound = new Set()
    for (const statement of sf.statements) {
      const isImport = ts.isImportDeclaration(statement)
      const isExport = ts.isExportDeclaration(statement)
      if (!(isImport || isExport) || !statement.moduleSpecifier || !ts.isStringLiteral(statement.moduleSpecifier)) continue
      const specifier = statement.moduleSpecifier.text
      const bindings = isImport ? statement.importClause?.namedBindings : statement.exportClause
      if (!bindings || !('elements' in bindings)) {
        if (isImport && statement.importClause?.name) bound.add(statement.importClause.name.text)
        continue
      }
      const target = specifier.startsWith('.') ? resolveSpecifier(file, specifier) : null
      const exported = target ? exportedNames(target) : null
      const typesFile = target ? path.join(path.dirname(target), 'types.ts') : null
      const typesExports = typesFile && typesFile !== target ? exportedNames(typesFile) : null

      const stay = []
      const go = []
      let dropped = false
      for (const element of bindings.elements) {
        const name = (element.propertyName ?? element.name).text
        const local = element.name.text
        if (isImport && bound.has(local)) { dropped = true; continue }
        if (isImport) bound.add(local)
        if (exported && !exported.has(name) && typesExports?.has(name)) {
          if (typesFile === file) { dropped = true; continue }
          go.push(element.getText(sf))
        }
        else stay.push(element.getText(sf))
      }
      if (go.length === 0 && !dropped) continue
      const keyword = isImport ? 'import' : 'export'
      const clauseTypeOnly = isImport ? statement.importClause.isTypeOnly : statement.isTypeOnly
      const head = `${keyword}${clauseTypeOnly ? ' type' : ''}`
      const lines = []
      if (stay.length > 0) lines.push(`${head} { ${stay.join(', ')} } from '${specifier}'`)
      if (go.length > 0) lines.push(`${head} { ${go.join(', ')} } from '${toSpecifier(path.dirname(file), typesFile)}'`)
      edits.push({ start: statement.getStart(sf), end: statement.getEnd(), text: lines.join('\n') })
      moved += go.length
    }

    let out = text
    for (const edit of edits.sort((a, b) => b.start - a.start)) out = out.slice(0, edit.start) + edit.text + out.slice(edit.end)

    // `import('./x').Name` type queries: the same rule, inline.
    out = out.replace(/import\((['"])(\.[^'"]+)\1\)\.(\w+)/g, (whole, quote, specifier, name) => {
      const target = resolveSpecifier(file, specifier)
      if (!target || exportedNames(target).has(name)) return whole
      const typesFile = path.join(path.dirname(target), 'types.ts')
      if (!exportedNames(typesFile).has(name)) return whole
      moved++
      return typesFile === file ? name : `import(${quote}${toSpecifier(path.dirname(file), typesFile)}${quote}).${name}`
    })

    if (out === text) continue
    files++
    if (WRITE || process.argv.includes('--repoint')) writeFileSync(file, out)
  }
  console.log(`repoint: ${moved} names in ${files} files point at their folder's types.ts now.`)
}

if (process.argv.includes('--repoint')) repointDangling()
else {
  main()
  if (WRITE) repointDangling()
}
